use std::sync::OnceLock;

/// A build-generated table, decompressed once on first access and then shared across threads.
pub(crate) struct CompressedTable {
    data: &'static [u8],
    decoded: OnceLock<Box<[u8]>>,
}

impl CompressedTable {
    /// Store a little-endian u32 size followed by a complete zlib stream without allocating.
    pub(crate) const fn new(data: &'static [u8]) -> Self {
        Self {
            data,
            decoded: OnceLock::new(),
        }
    }

    /// Return the cached table, allocating and validating its build-generated bytes on first access.
    pub(crate) fn get(&'static self) -> &'static [u8] {
        self.decoded.get_or_init(|| decompress(self.data))
    }
}

fn decompress(data: &[u8]) -> Box<[u8]> {
    let (size, compressed) = data
        .split_first_chunk::<4>()
        .expect("build-generated encoding tables have a four-byte uncompressed size prefix");
    let size = usize::try_from(u32::from_le_bytes(*size))
        .expect("build-generated encoding table sizes fit the target address space");
    let mut decoded = vec![0; size].into_boxed_slice();
    let (status, consumed, written) = gix_zlib::Inflate::default()
        .once(compressed, &mut decoded)
        .expect("build-generated encoding tables contain valid zlib streams");
    assert_eq!(
        status,
        gix_zlib::Status::StreamEnd,
        "build-generated encoding table streams end within their declared uncompressed size"
    );
    assert_eq!(
        consumed,
        compressed.len(),
        "build-generated encoding tables contain exactly one zlib stream without trailing bytes"
    );
    assert_eq!(
        written, size,
        "build-generated encoding tables decompress to their exact declared size"
    );
    decoded
}

#[cfg(test)]
mod tests {
    use super::{CompressedTable, decompress};

    const ASCII: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/ASCII.bin"));

    #[test]
    fn lazy_initialization_reuses_storage_across_threads() -> gix_error::TestResult {
        static TABLE: CompressedTable = CompressedTable::new(ASCII);
        assert!(
            TABLE.decoded.get().is_none(),
            "construction must not decompress the table"
        );
        std::thread::scope(|scope| {
            let threads: Vec<_> = (0..8).map(|_| scope.spawn(|| TABLE.get())).collect();
            for thread in threads {
                let decoded = thread
                    .join()
                    .expect("valid build-generated tables decompress on every thread");
                assert_eq!(
                    decoded,
                    include_bytes!("tables/ASCII.bin"),
                    "cached bytes match the raw table"
                );
                assert!(
                    std::ptr::eq(decoded, TABLE.get()),
                    "all threads and repeated accesses share the same allocation"
                );
            }
        });
        assert!(TABLE.decoded.get().is_some(), "first access must populate the cache");
        Ok(())
    }

    #[test]
    fn generated_tables_match_raw_bytes() -> gix_error::TestResult {
        macro_rules! check {
            ($($name:literal),+ $(,)?) => {
                $({
                    static TABLE: CompressedTable = CompressedTable::new(include_bytes!(concat!(env!("OUT_DIR"), "/", $name, ".bin")));
                    assert_eq!(
                        TABLE.get(),
                        include_bytes!(concat!("tables/", $name, ".bin")),
                        concat!($name, " must decompress byte-for-byte to its source table")
                    );
                })+
            };
        }
        check!(
            "ASCII",
            "BIG5-HKSCS",
            "BIG5",
            "CP1125",
            "CP437",
            "CP850",
            "CP866",
            "CP932",
            "CP949",
            "EUC-JP",
            "EUC-KR",
            "GB18030",
            "GB2312",
            "GBK",
            "ISO-8859-1",
            "ISO-8859-10",
            "ISO-8859-11",
            "ISO-8859-13",
            "ISO-8859-14",
            "ISO-8859-15",
            "ISO-8859-16",
            "ISO-8859-2",
            "ISO-8859-3",
            "ISO-8859-4",
            "ISO-8859-5",
            "ISO-8859-6",
            "ISO-8859-7",
            "ISO-8859-8",
            "ISO-8859-9",
            "KOI8-R",
            "KOI8-U",
            "MAC-CYRILLIC",
            "MACINTOSH",
            "SHIFT_JIS",
            "TIS-620",
            "WINDOWS-1250",
            "WINDOWS-1251",
            "WINDOWS-1252",
            "WINDOWS-1253",
            "WINDOWS-1254",
            "WINDOWS-1255-combining",
            "WINDOWS-1255",
            "WINDOWS-1256",
            "WINDOWS-1257",
            "WINDOWS-1258-combining",
            "WINDOWS-1258",
            "WINDOWS-874",
            "gb18030-encode-ranges",
            "gb18030-ranges",
        );
        Ok(())
    }

    #[test]
    fn malformed_generated_data_is_rejected() -> gix_error::TestResult {
        let mut cases = vec![
            ("missing size prefix", Vec::new()),
            ("truncated size prefix", ASCII[..3].to_vec()),
            ("missing zlib stream", ASCII[..4].to_vec()),
            ("truncated zlib stream", ASCII[..ASCII.len() / 2].to_vec()),
            ("truncated checksum", ASCII[..ASCII.len() - 1].to_vec()),
        ];
        let mut corrupted = ASCII.to_vec();
        corrupted[4] = 0;
        cases.push(("corrupted zlib header", corrupted));
        let mut corrupted = ASCII.to_vec();
        *corrupted.last_mut().expect("generated zlib streams contain a checksum") ^= 0xff;
        cases.push(("corrupted checksum", corrupted));
        let mut trailing = ASCII.to_vec();
        trailing.push(0);
        cases.push(("trailing byte", trailing));
        let mut concatenated = ASCII.to_vec();
        concatenated.extend_from_slice(&ASCII[4..]);
        cases.push(("concatenated zlib streams", concatenated));
        let size = u32::try_from(include_bytes!("tables/ASCII.bin").len())?;
        for (case, size) in [("size too small", size - 1), ("size too large", size + 1)] {
            let mut incorrect_size = ASCII.to_vec();
            incorrect_size[..4].copy_from_slice(&size.to_le_bytes());
            cases.push((case, incorrect_size));
        }
        for (case, data) in cases {
            assert!(
                std::panic::catch_unwind(|| decompress(&data)).is_err(),
                "{case} must be rejected rather than cached"
            );
        }
        Ok(())
    }
}
